import json
S = []
def seg(scene, text, kick=None, **params): S.append({"scene": scene, "text": text, "kick": kick, "params": params})
def card(num, title, icon): S.append({"scene": "title", "text": None, "kick": None, "params": {"num": num, "title": title, "icon": icon}, "dur": 3.0})
S.append({"scene": "playground", "text": None, "kick": None, "params": {"bell": True}, "dur": 4.0})
seg("versus", "What if your future home becomes cheaper... but your retirement becomes more expensive?", None, left="house_down", right="pension_up")
seg("versus", "What if companies desperately need workers... but hospitals cannot find enough nurses?", None, left="hiring", right="hospital")
seg("versus", "And what if governments offer people money to have babies... but the next generation still gets smaller?", None, left="baby_money", right="shrinking")
seg("playground", "This might sound like the beginning of a science-fiction movie. But the demographic shift behind it is already happening.", "ALREADY HAPPENING")
seg("waffle", "According to the United Nations' World Fertility 2024 report, fertility was below replacement level in 55 percent of the world's countries and areas.", "UN WORLD FERTILITY 2024")
seg("pyramid", "That does not mean humanity is about to disappear. It means something more complicated: many societies are moving toward a future with fewer young people and a larger share of older adults.", "FEWER YOUNG, MORE OLDER ADULTS")
seg("generations", "So, what happens when an economy built around each generation being bigger meets a generation that is smaller?", None)
seg("fiveFutures", "Let's explore five possible futures.", "5 POSSIBLE FUTURES")
seg("tree", "First, we need to understand one number: 2.1.", None, gens=[10, 9, 7, 5])
seg("twoPointOne", "In countries with low mortality, around 2.1 children per woman is the fertility level needed for one generation to replace itself over the long term, without migration.", "REPLACEMENT LEVEL")
seg("twoPointOne", "It is a population average, not a target for every family.", "AN AVERAGE, NOT A TARGET", mode="avg")
seg("rateChart", "And the fertility rate is not the same as the number of babies born this year. It estimates how many children a woman would have if current age-specific birth rates continued throughout her reproductive life.", "FERTILITY RATE IS NOT BIRTHS THIS YEAR")
seg("couples", "Now imagine 100 couples.", "100 COUPLES", rows=[["100 couples", 10, "parent"]])
seg("couples", "In a simplified example, if every couple has two children, they have 200 children altogether.", "2 CHILDREN EACH", rows=[["100 couples", 10, "parent"], ["200 children", 20, "kid"]])
seg("couples", "If those couples average just one child, the next generation has only 100.", "1 CHILD EACH", rows=[["100 couples", 10, "parent"], ["100 children", 10, "kid"]])
seg("couples", "If that pattern continues, the following generation could be smaller again.", "SMALLER AGAIN", rows=[["100 couples", 10, "parent"], ["100 children", 10, "kid"], ["50 grandchildren", 5, "kid"]])
seg("complex", "Real populations are more complicated. People live longer, move between countries, and have children at different ages.", "REAL LIFE IS MORE COMPLICATED")
seg("growthChart", "A country can even keep growing for years after fertility falls below replacement.", "POPULATION MOMENTUM")
seg("pyramid", "But over decades, smaller birth cohorts change the shape of society. And that brings us to our first scenario.", "THE SHAPE OF SOCIETY", mode="late")
card(1, "WHAT IF THERE ARE FEWER WORKERS?", "workers")
seg("town", "Imagine a town twenty-five years from now. Its largest generation is retiring. But the generation entering work is much smaller.", "25 YEARS FROM NOW", mode="retire")
seg("town", "The local supermarket needs staff. Construction companies need electricians. The hospital needs carers.", "HELP WANTED", mode="signs")
seg("town", "At first, that could be good news for some workers. Employers may offer higher wages, better training, or more flexible hours because people are harder to recruit.", "HIGHER WAGES  ·  TRAINING  ·  FLEXIBLE HOURS", mode="wages")
seg("bakery", "But now imagine you own a small bakery. You raise wages to attract staff. Your supplier has done the same. So has the delivery company.", "YOUR SMALL BAKERY", mode="costs")
seg("bakery", "Your costs increase. You might raise prices, shorten opening hours, buy equipment, or close.", "COSTS RISE", mode="options")
seg("demand", "That does not mean every labour shortage creates inflation, or that every business loses. Demand changes too. Fewer children could mean less demand for some school supplies, while an older population needs more healthcare.", "DEMAND CHANGES TOO")
seg("matching", "The challenge is matching the workers we have with the services people need.", "MATCHING WORKERS TO NEEDS")
seg("productivity", "And here is the crucial distinction: A smaller economy is not automatically a poorer society. If fewer workers produce more value per person, living standards can still improve.", "SMALLER DOES NOT MEAN POORER")
seg("piggy", "Which takes us to the biggest financial question.", None, mode="question")
card(2, "WHAT IF RETIREMENT GETS HARDER?", "piggy")
seg("dinner", "Imagine a shared dinner. Ten people contribute money to feed themselves and a few relatives.", "A SHARED DINNER", retired=0)
seg("dinner", "Over time, several contributors retire. Now fewer people are earning, while more people still need dinner.", "FEWER EARNING", retired=4)
seg("dinner", "Many public pension systems face a version of this problem: today's workers help finance today's retirees.", "TODAY'S WORKERS FUND TODAY'S RETIREES", retired=4, link=True)
seg("levers", "As populations age, governments may face difficult choices. Increase contributions. Raise taxes. Adjust benefits. Encourage longer working lives. Or move money away from other priorities.", "DIFFICULT CHOICES", items=["Increase contributions", "Raise taxes", "Adjust benefits", "Longer working lives", "Move money from other priorities"], words=["contributions", "taxes", "benefits", "working", "priorities"])
seg("pillars", "But pensions are not identical everywhere. Some rely more on taxes, some on contributions, and others include substantial invested savings.", "PENSIONS DIFFER")
seg("piggy", "An ageing population does not automatically mean your pension disappears. It means the system may need to change.", "CHANGE, NOT DISAPPEAR", mode="fix")
seg("twoWorkers", "Now consider two people asked to work longer. One has a flexible office job. The other has spent forty years lifting heavy materials. The same retirement age can affect them very differently.", "SAME RETIREMENT AGE?")
seg("twoWorkers", "So the question is not simply, 'Can people work longer?' It is, 'Who can work longer, under what conditions, and with what support?'", "WHO? UNDER WHAT CONDITIONS? WITH WHAT SUPPORT?", mode="q")
seg("elders", "And remember: longer lives are an achievement. The problem is failing to adapt our institutions to them.", "LONGER LIVES ARE AN ACHIEVEMENT")
card(3, "WHAT IF HOUSES BECOME CHEAPER?", "house")
seg("houses", "Here is the scenario many younger viewers might welcome. Fewer people. More empty homes. Lower prices.", "FEWER PEOPLE, LOWER PRICES?")
seg("houses", "Possible? Yes, in some places. Guaranteed everywhere? Absolutely not.", "POSSIBLE IN SOME PLACES. NOT GUARANTEED.", mode="no")
seg("townCity", "Imagine two locations in the same country. A small town loses younger residents. Its school closes. Shops struggle. Housing demand weakens.", "A SMALL TOWN", focus="town")
seg("townCity", "Meanwhile, the capital city keeps attracting students, migrants, and workers. Housing there can remain expensive, even while the national population shrinks.", "THE CAPITAL CITY", focus="city")
seg("households", "There is another twist. Homes are occupied by households, not by population totals. If more people live alone, a country can need more homes even without adding more people.", "HOUSEHOLDS, NOT HEADCOUNT")
seg("accessible", "Older residents may also need different housing: smaller properties, accessible entrances, and locations close to healthcare.", "DIFFERENT HOUSING NEEDS")
seg("townCity", "So demographic change could create an unusual future: Empty houses in places where jobs have disappeared... and housing shortages where people still need to live.", "EMPTY HOMES AND SHORTAGES", focus="both")
seg("farHouse", "A cheap house is much less useful if the nearest employer, hospital, or supermarket is far away.", "CHEAP, BUT FAR AWAY")
card(4, "WHAT IF AI FILLS THE GAP?", "robot")
seg("aiTools", "Now imagine a different response. Instead of trying to replace every missing worker, we help each worker accomplish more.", "HELP EACH WORKER DO MORE", mode="intro")
seg("aiTools", "Software reduces paperwork. Machines handle repetitive factory tasks. Better equipment allows older workers to remain employed comfortably.", None, mode="list")
seg("team", "In a simplified example, if a team becomes ten percent smaller but each remaining worker becomes productive enough, total output could be maintained. That is why productivity matters so much.", "PRODUCTIVITY MATTERS")
seg("obstacles", "But 'AI will fix it' skips several difficult steps. Technology costs money. Businesses need time to adopt it. Workers need training. And the benefits may not reach everyone equally.", "\"AI WILL FIX IT\"?", words=["money", "time", "training", "equally"])
seg("care", "Most importantly, producing more digital content is different from helping someone shower, repairing a water pipe, or comforting a frightened patient. Some tasks are much harder to automate than others.", "HARD TO AUTOMATE")
seg("twoFutures", "So imagine two futures. In one, technology helps a smaller workforce support a good quality of life. In the other, productivity gains concentrate in a few companies while essential services remain understaffed.", "TWO FUTURES", mode="both")
seg("twoFutures", "The technology matters. How we use it matters just as much.", "HOW WE USE IT MATTERS", mode="both")
card(5, "WHAT IF GOVERNMENTS TRY TO REVERSE IT?", "baby")
seg("babyBonus", "Suppose a government announces a baby bonus. Will births suddenly return to replacement level? There is no guaranteed result.", "A BABY BONUS?")
seg("checklist", "Because deciding to have a child involves much more than one payment. Can we afford a suitable home? Is childcare available? Will we lose income? Can we balance work and family life? Do we actually want to become parents?", "MORE THAN ONE PAYMENT", items=["Can we afford a suitable home?", "Is childcare available?", "Will we lose income?", "Can we balance work and family?", "Do we want to be parents?"], words=["afford", "childcare", "income", "balance", "actually"])
seg("couplesChoice", "Some people want fewer children. Others want children but face barriers. Those are different situations, and policy needs to recognise that.", "DIFFERENT SITUATIONS")
seg("policyCards", "Affordable childcare, parental leave, stable employment, and housing can make family life easier.", "MAKING FAMILY LIFE EASIER")
seg("babyTimeline", "But even if births increase tomorrow, those babies will not become nurses or taxpayers next year. They need roughly two decades to enter the workforce.", "ABOUT 20 YEARS")
seg("migration", "What about immigration? It can bring working-age people into a country much sooner. But successful migration also requires housing, infrastructure, fair working conditions, and ways to recognise people's skills.", "IMMIGRATION", words=["housing", "infrastructure", "fair", "skills"])
seg("migrationGlobe", "And migration moves people between countries. It does not increase the global population. It can be part of the response, alongside training, productivity, and better opportunities for people already living there.", "PART OF THE RESPONSE")
seg("noSwitch", "There is no single switch that fixes demographic change.", "NO SINGLE SWITCH")
seg("triple", "But here is the twist. A smaller future generation does not automatically mean a worse future.", "THE TWIST")
seg("twoFutures", "It could mean fewer pressures on some resources, more investment per child, and stronger incentives to improve productivity.", "IT COULD BE BETTER", mode="bright")
seg("twoFutures", "It could also mean stretched care services, struggling communities, and difficult financial choices.", "OR HARDER", mode="grey")
seg("triple", "Both outcomes are possible. What matters is the pace of change, and whether societies prepare.", "PACE OF CHANGE + PREPARATION")
seg("worldPaths", "The world is not following one demographic path. Some populations are still growing rapidly, while others are ageing and shrinking.", "NOT ONE PATH")
seg("society", "So the challenge is not simply getting everyone to have more babies. It is building a society where people can make real choices about family life, and where a good standard of living does not depend entirely on having more people every generation.", "REAL CHOICES")
seg("bigQuestion", "Because the biggest question is not: 'What if there are fewer of us?' It is: 'What if our systems never learn how to adapt?'", None)
seg("cta", "If your country's next generation were smaller, what would you change first: housing, retirement, or the way we work? Tell us in the comments.", "WHAT WOULD YOU CHANGE FIRST?")
S.append({"scene": "endcard", "text": None, "kick": None, "params": {}, "dur": 4.0})
json.dump(S, open("segments.json", "w"), indent=1)
print(len(S), "segments,", sum(len(s["text"].split()) for s in S if s["text"]), "words")
